import { useState, useEffect } from "react";
import OverviewCards from "../components/Analytics/OverviewCards";
import DistributorTable from "../components/Analytics/DistributorTable";
import ShopTable from "../components/Analytics/ShopTable";
import TopShopsChart from "../components/Analytics/TopShopsChart";
import MoMTrendChart from "../components/Analytics/MoMTrendChart";
import ComparisonChart from "../components/Analytics/ComparisonChart";
import FilterBar from "../components/Filters/FilterBar";
import { getOverview, getShops, getMoMTrend, getTopShops, getDistributors } from "../services/api";

export default function Dashboard() {
  const [filters, setFilters] = useState({ month: "", year: "", distributor: "" });
  const [distributors, setDistributors] = useState([]);
  const [overview, setOverview] = useState(null);
  const [shops, setShops] = useState([]);
  const [trend, setTrend] = useState([]);
  const [topShops, setTopShops] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  // Load distributor list once
  useEffect(() => {
    getDistributors()
      .then((data) => setDistributors(data.map((d) => d.distributor_name)))
      .catch(() => {});
  }, []);

  // Reload analytics when filters change
  useEffect(() => {
    const params = Object.fromEntries(Object.entries(filters).filter(([, v]) => v));
    setLoading(true);
    setError("");
    Promise.all([
      getOverview(params),
      getShops(params),
      getMoMTrend(params),
      getTopShops({ ...params, limit: 10 }),
    ])
      .then(([ov, sh, tr, ts]) => {
        setOverview(ov);
        setShops(sh);
        setTrend(tr);
        setTopShops(ts);
      })
      .catch((err) => setError(err.message || "Failed to load data"))
      .finally(() => setLoading(false));
  }, [filters]);

  return (
    <div style={{ maxWidth: 960, margin: "0 auto", padding: "2rem 1rem" }}>
      <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", marginBottom: "1.5rem", flexWrap: "wrap", gap: 12 }}>
        <div>
          <h1 style={{ margin: 0, fontSize: 22, fontWeight: 500 }}>Dashboard</h1>
          <p style={{ margin: "4px 0 0", fontSize: 14, color: "var(--color-text-secondary)" }}>
            Shop-wise sales analytics across all distributors
          </p>
        </div>
        <FilterBar filters={filters} onChange={setFilters} distributors={distributors} />
      </div>

      {error && (
        <div style={{
          background: "var(--color-background-danger)",
          border: "0.5px solid var(--color-border-danger)",
          borderRadius: "var(--border-radius-md)",
          padding: "12px 16px",
          fontSize: 13,
          color: "var(--color-text-danger)",
          marginBottom: "1.25rem",
        }}>
          <i className="ti ti-circle-x" style={{ fontSize: 14, marginRight: 6 }} aria-hidden />{error}
        </div>
      )}

      <div style={{ display: "flex", flexDirection: "column", gap: "1.5rem" }}>
        <OverviewCards data={overview} loading={loading} />

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "1rem" }}>
          <TopShopsChart data={topShops} loading={loading} />
          <MoMTrendChart data={trend} loading={loading} />
        </div>

        <DistributorTable rows={overview?.by_distributor || []} loading={loading} />

        <ShopTable rows={shops} loading={loading} />
      </div>
    </div>
  );
}
